  "bioavailability_prediction": "high",
  "claims": [
    {
      "card_ids": ["C11"],
      "claim": "A highly transferable analogue sharing the piperazine-aminopyridine scaffold had 77% absolute oral bioavailability in fed healthy volunteers, directly supporting F≥20%.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C05"],
      "claim": "The same analogue in fasted healthy volunteers had 57% absolute oral bioavailability, showing high F regardless of prandial state.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C06"],
      "claim": "Brigatinib, a structurally related kinase inhibitor with piperazine and aminopyridine, had approximately 46% oral bioavailability, above the 20% threshold.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C08"],
      "claim": "Trametinib, a kinase inhibitor, had 72% oral bioavailability in fasted patients, supporting high F for this class.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C02"],
      "claim": "Imatinib, a kinase inhibitor with a piperazine-containing side chain, had 98% absolute bioavailability, demonstrating that ionizable piperazine does not preclude high F.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C07"],
      "claim": "Brepocitinib, a kinase inhibitor, had 75% absolute bioavailability, further supporting high F.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C01"],
      "claim": "Norfloxacin, despite ionizable groups, had mean approximately 40% systemic availability, above the threshold.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C10"],
      "claim": "Fasudil had 69% absolute bioavailability, supporting high F.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C09"],
      "claim": "Tacrolimus had approximately 20-25% oral bioavailability, meeting the F≥20% threshold, though it is less structurally relevant.",
      "evidence_role": "supportive"
    }
  ],
  "confidence": "high",
  "decision_summary": "The physicochemical prior predicts low F, but multiple highly transferable experimental records from structurally related kinase inhibitors and other ionizable drugs consistently show absolute oral bioavailability ≥20% (46-98%). The query's piperazine-aminopyridine kinase-inhibitor scaffold is well represented, so the experimental evidence overrides the prior and supports high F.",
  "evidence_gaps": [
    "No direct absolute F measurement for the exact query molecule in the provided evidence; prediction relies on highly transferable analogues.",
    "No explicit human efflux/metabolism data for the query, but high F in close analogues suggests these are not dominant.",
    "C03 (mCPP) has zero transfer score and a wide 12-84% F range, so it is not informative."
  ],
  "new_evidence_assessment": [
